      centralQuestions: ['How can scripture form readers without being confined to surface meaning?', 'How do Father, Logos, and Spirit relate before Nicene terminology?', 'How can providence coexist with created freedom?', 'What makes embodiment and resurrection compatible with spiritual transformation?', 'Does divine correction finally restore every rational creature?'],
      majorIdeasDetailed: [
        {name: 'Spiritual interpretation', explanation: 'Literal wording, moral formation, doctrinal coherence, and spiritual meaning cooperate as the Logos educates readers through scripture.', whyItMatters: 'It makes interpretation a disciplined practice of transformation, while raising enduring questions about constraint and allegory.'},
        {name: 'Eternal Logos and divine pedagogy', explanation: 'The Son is eternally generated Wisdom and Logos who reveals the Father and orders rational creation according to capacity.', whyItMatters: 'It links Trinitarian reflection, cosmology, scripture, and salvation before later Nicene vocabulary stabilized.'},
        {name: 'Created freedom', explanation: 'Rational creatures are not made good or evil by nature; their different conditions are connected with changeable agency under providence.', whyItMatters: 'It protects divine justice but creates difficult questions about prior causes, embodiment, foreknowledge, and repeated correction.'},
        {name: 'Restorative judgment', explanation: 'Divine punishment is frequently therapeutic and aims to remove vice rather than preserve it forever.', whyItMatters: 'It grounds powerful restoration readings, while the extent and certainty of final salvation remain textually disputed.'},
      ],
      keyWorksDetailed: [
        {title: 'On First Principles', approximateYear: 225, summary: 'A four-book synthesis of God, rational beings, world, freedom, scripture, and theological method, complete only in Rufinus’s Latin translation with partial Greek witnesses.', whyItMatters: 'It is indispensable and also the clearest warning against treating a translated, excerpted text as an untouched Greek original.'},
        {title: 'Against Celsus', approximateYear: 248, summary: 'An eight-book Greek response to a learned pagan critic of Christian claims and communities.', whyItMatters: 'It shows Origen’s public reasoning, philosophical discrimination, and reconstruction of an opponent.'},
        {title: 'Commentary on John', approximateYear: 230, summary: 'A large, partly surviving Greek commentary developing Logos theology through close gospel exegesis.', whyItMatters: 'It keeps doctrinal construction inside Origen’s primary practice of interpreting scripture.'},
        {title: 'On Prayer', approximateYear: 233, summary: 'A substantially surviving Greek treatment of providence, freedom, the Lord’s Prayer, desire, and prayerful practice.', whyItMatters: 'It offers a comparatively secure and accessible entry into his practical philosophical theology.'},
      ],
      lifeEvents: [{approximateYear: 185, label: 'Born in Alexandria', description: 'The conventional date is reconstructed from Eusebius’s chronology.'}, {year: 202, label: 'Persecution and death of Leontius', description: 'Eusebius places his father’s martyrdom under Septimius Severus and portrays the young Origen’s response.'}, {approximateYear: 215, label: 'Major Alexandrian teaching and scholarship', description: 'Origen develops commentaries and the Hexapla with patrons, stenographers, and copyists.'}, {approximateYear: 232, label: 'Moves to Caesarea', description: 'Conflict with Demetrius and ordination outside Alexandria accompany a new teaching and preaching setting.'}, {approximateYear: 250, label: 'Imprisoned during the Decian persecution', description: 'Eusebius reports torture and survival; later tradition connects his death to its effects.'}, {approximateYear: 253, label: 'Dies, probably at Tyre', description: 'The date and location remain conventional rather than precisely documented.'}],
      intellectualDevelopment: ['Alexandrian classroom, textual, and commentary work precedes the Caesarean preaching and mature apologetic setting.', 'Different genres test speculative proposals with different levels of confidence; exploratory language should not automatically become doctrine.', 'Later translation, excerpting, controversy, and Origenist developments make a simple early-versus-late doctrinal chronology impossible.'],
      influencesReceived: ['Christian scriptures and the church’s rule of faith', 'Jewish scriptural interpretation and language study', 'Plato and Middle Platonist traditions', 'Alexandrian philology and textual criticism'], influenceOnLaterThought: ['Gregory of Nyssa and Cappadocian theology', 'Didymus, Evagrius, and Christian ascetic exegesis', 'Jerome and Rufinus through both reception and controversy', 'Later debates over freedom, embodiment, purification, and universal restoration'],
      influencedByIds: ['plato'], influencedIds: ['gregory-nyssa'], disagreementIds: [],
      controversiesOrInterpretiveTensions: ['Most of On First Principles survives through Rufinus’s interventionist Latin translation.', 'Greek fragments may be excerpted by admirers or hostile witnesses.', 'The preexistence and fall of rational creatures are less securely recoverable than textbook narratives suggest.', 'The nature of the resurrection body and final embodiment remains disputed.', 'Universal restoration, including the devil’s fate, cannot be reduced to one unambiguous formula.', 'Later Origenism and sixth-century condemnations do not map cleanly onto Origen’s extant writings.'],
      commonMisunderstandings: ['Origen’s surviving corpus is not wholly Greek or textually uniform.', 'Spiritual interpretation does not mean that literal or historical senses never matter.', 'He does not identify matter or embodiment as an independently evil principle.', 'Pre-Nicene vocabulary cannot be graded by later creeds without historical translation.', '“Origenism” is not simply everything Origen personally taught.', 'The status and target of the 553 condemnations require qualification.'],
      schoolMemberships: ['Early Christian teacher and presbyter operating in Alexandrian and Caesarean ecclesial and scholarly networks; “Christian Platonist” describes a modern comparison, not membership in a pagan Platonic school.'],
      branchContributions: [{branchId: 'philosophy-of-religion', summary: 'Developed an integrated account of revelation, reason, divine language, freedom, providence, prayer, and salvation.'}, {branchId: 'epistemology', summary: 'Made philology, textual comparison, layered reading, and reader formation central to the pursuit of scriptural knowledge.'}, {branchId: 'metaphysics', summary: 'Explored incorporeal divine life, created rational natures, embodiment, evil, and cosmic order.'}, {branchId: 'ethics', summary: 'Defended creaturely agency against fatalism while placing choices within divine foreknowledge and pedagogy.'}],
      branchMemberships: [{branchId: 'philosophy-of-religion', status: 'major', note: 'Major early Christian source for philosophical theology and scriptural reason.', confidence: 'high'}, {branchId: 'epistemology', status: 'major', note: 'His commentaries, homilies, Hexapla, and On First Principles made interpretation a comprehensive discipline of knowledge.', confidence: 'high'}, {branchId: 'metaphysics', status: 'major', note: 'His account of divine and created being, rational creatures, bodies, and evil is philosophically extensive.', confidence: 'high'}, {branchId: 'platonism', status: 'later-reception', note: 'Receives and transforms Platonist concepts within Christian exegesis; not a documented member of a pagan Platonic school.', confidence: 'medium'}],
